const json = (res, status, data, headers = {}) => { res.writeHead(status, {'content-type':'application/json; charset=utf-8', ...headers}); res.end(JSON.stringify(data)); };
const body = async (req) => {
  let raw = ''; for await (const chunk of req) { raw += chunk; if (raw.length > 1e6) throw Object.assign(new Error('PAYLOAD_TOO_LARGE'), {status: 413}); }
  try { return JSON.parse(raw || '{}'); } catch { throw Object.assign(new Error('INVALID_JSON'), {status: 400}); }
};
const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email || '');
function auth(req) {
  const token = req.headers.authorization?.replace(/^Bearer\s+/i, '');
  try { return verifyToken(token, config.jwtSecret); } catch { throw Object.assign(new Error('UNAUTHORIZED'), {status: 401}); }
}
