  const unsubMatch=url.pathname.match(/^\/unsubscribe\/([a-f0-9]{32})$/);if(unsubMatch){const message=store.state.emailMessages.find(x=>x.token===unsubMatch[1]);if(message&&!store.state.emailSuppressions.some(x=>x.tenantId===message.tenantId&&x.email===message.email)){store.state.emailSuppressions.push({tenantId:message.tenantId,email:message.email,reason:'unsubscribe',createdAt:new Date().toISOString()});store.state.emailEvents.push({id:crypto.randomUUID(),messageId:message.id,type:'unsubscribe',at:new Date().toISOString(),metadata:{}});await store.persist()}res.writeHead(200,{'content-type':'text/html; charset=utf-8','cache-control':'no-store'});return res.end('<!doctype html><meta charset="utf-8"><title>已退订</title><main style="font:16px system-ui;max-width:560px;margin:80px auto"><h1>退订成功</h1><p>该地址已加入禁止发送名单，不会再收到营销邮件。</p></main>')}
