  if(req.method==='GET'&&url.pathname.startsWith('/api/templates/')){const item=templateById(decodeURIComponent(url.pathname.split('/').pop()));return item?json(res,200,item):json(res,404,{error:{code:'TEMPLATE_NOT_FOUND'}});}
