async function staticFile(req, res, url) {
  if(url.pathname.startsWith('/sites/')){const relative=normalize(url.pathname.replace(/^\/sites\//,'')).replace(/^(\.\.(\/|\\|$))+/,'');let file=join(root,'.data','published',relative);try{if((await stat(file)).isDirectory())file=join(file,'index.html');const content=await readFile(file);const extension=extname(file);res.writeHead(200,{'content-type':mime[extension]||'application/octet-stream','cache-control':extension==='.html'?'public, s-maxage=300, stale-while-revalidate=86400':'public, max-age=31536000, immutable'});return res.end(content)}catch{return json(res,404,{error:{code:'PUBLISHED_SITE_NOT_FOUND'}})}}
  const app = url.pathname.startsWith('/admin') ? 'admin' : 'web';
  const relative = app === 'admin' ? url.pathname.replace(/^\/admin\/?/, '') : url.pathname.slice(1);
  const safe = normalize(relative || 'index.html').replace(/^(\.\.(\/|\\|$))+/, '');
  let file = join(root, 'apps', app, 'public', safe);
  try { if ((await stat(file)).isDirectory()) file = join(file, 'index.html'); }
  catch { file = join(root, 'apps', app, 'public', 'index.html'); }
  const content = await readFile(file);const extension=extname(file);const cacheControl=extension==='.html'?'public, s-maxage=300, stale-while-revalidate=86400':/\.(?:css|js|svg|png|jpe?g|webp|avif|woff2)$/.test(extension)?'public, max-age=31536000, immutable':'public, max-age=3600';
  res.writeHead(200, {'content-type':mime[extension] || 'application/octet-stream','cache-control':cacheControl,'vary':'accept-encoding'}); res.end(content);
}
